coworkers = []
page = 0
while True:
    resp = apis.phone.search_contacts(access_token=[REDACTED], relationship='coworker', page_index=page, page_limit=20)
    if not isinstance(resp, list) or len(resp) == 0:
        break
    coworkers.extend(resp)
    if len(resp) < 20:
        break
    page += 1
print(len(coworkers))
for c in coworkers:
    print(c['contact_id'], c['first_name'], c['last_name'], c['email'], c['relationships'])

